def reading_room(articles):
    latest=max(a['date'] for a in articles).replace('-', '.')
    categories=[('latest','最新解读',None),('fusion','图像融合','图像融合'),('perception','三维感知','三维感知'),('benchmark','数据集与基准','数据集与基准')]
    buttons=''.join(f'<button type="button" data-reading-tab="{key}" aria-pressed="{str(i==0).lower()}" aria-controls="reading-{key}">{name}<span>{sum(a["section"]=="论文解读" and (topic is None or topic in a["topics"]) for a in articles)}</span></button>' for i,(key,name,topic) in enumerate(categories))
    groups=[]
    for key,name,topic in categories:
        selected=[a for a in articles if a['section']=='论文解读' and (topic is None or topic in a['topics'])][:3]
        cards=[]
        for i,a in enumerate(selected):
            theme='perception' if '三维感知' in a['topics'] else 'benchmark' if '数据集与基准' in a['topics'] else 'fusion'
            motif=''.join(f'<i style="--i:{n}"></i>' for n in range(6))
            cards.append(f'''<article class="reading-card"><a class="reading-cover cover-{theme}" href="{E(a['url'])}" target="_blank" rel="noopener noreferrer" aria-label="阅读：{E(a['title'])}"><span class="cover-top">MMIFUSION / READING NOTES <span>0{i+1}</span></span><div class="cover-motif" aria-hidden="true">{motif}</div><span class="cover-topic">{E(a['topics'][0] if a['topics'] else '研究阅读')} <b>↗</b></span></a><div class="reading-card-body"><div class="reading-meta"><span>{E(a['venue'] or '研究解读')}</span><time datetime="{a['date']}">{a['date'].replace('-','.')}</time></div><h3><a href="{E(a['url'])}" target="_blank" rel="noopener noreferrer">{E(a['title'])}</a></h3><div class="reading-tags">{''.join('<span>'+E(t)+'</span>' for t in a['topics'][:2])}</div><a class="reading-link" href="{E(a['url'])}" target="_blank" rel="noopener noreferrer">前往公众号阅读全文 <span>↗</span></a></div></article>''')
        groups.append(f'<div class="reading-group" id="reading-{key}" data-reading-group="{key}"><h3 class="reading-group-name">{name}</h3><div class="reading-grid">{"".join(cards)}</div></div>')
    return f'''<section class="wrap section reading-section" id="reading"><div class="section-heading"><div><p class="eyebrow">01 / THE READING ROOM</p><h2>值得读，也值得继续探索。</h2><p>从研究问题出发，读懂方法背后的选择。</p></div><a class="text-link" href="papers.html">全部文章 <span>↗</span></a></div><div class="reading-tabs" aria-label="精选文章分类">{buttons}<a href="papers.html?saved=1">我的收藏 ☆</a></div>{''.join(groups)}<p class="reading-provenance">文章索引截至 {latest} · 会议期刊标签来自原始标题 · 封面为本站主题设计</p></section>'''

def research_paths(articles):
    paths=[('01','图像融合','从互补信息，走向融合表征。','红外与可见光、多曝光与多聚焦：跟进方法，回到数据和评测。','图像融合','metrics.html','理解评估指标'),('02','多模态感知','让感知走进更复杂的世界。','三维理解、自动驾驶与跨模态学习，从任务需求发现方法。','三维感知','teams.html','认识研究团队'),('03','配准与恢复','先对齐，再看清。','关注几何对齐、退化建模与恢复过程，建立完整的问题视角。','图像配准','papers.html?topic=图像恢复','继续阅读图像恢复')]
    cards=[]
    for num,title,subtitle,desc,topic,url,cta in paths:
        count=sum(topic in a['topics'] for a in articles)
        cards.append(f'<article class="path-card"><div class="path-number">{num}<span>RESEARCH PATH</span></div><h3>{title}</h3><strong>{subtitle}</strong><p>{desc}</p><div class="path-actions"><a href="papers.html?{E(urlencode({"topic":topic}))}">浏览 {count} 篇专题文章 ↗</a><a href="{url}">{cta} →</a></div></article>')
    return f'<section class="research-paths"><div class="wrap section"><div class="section-heading"><div><p class="eyebrow">02 / CHOOSE YOUR DIRECTION</p><h2>找到你的研究坐标。</h2><p>把分散的论文，串成可以继续深入的方向。</p></div></div><div class="path-grid">{"".join(cards)}</div></div></section>'

